op=[p('Orzel Bialy Pb2','99.97% secondary soft lead grade for battery manufacture.',O,'commercial',roles=['manufacturer'],typ='product',sector='energy_storage',sub='batteries',attributes={'reported_lead_purity_percent':99.97})]
