S=ev('https://www.globenewswire.com/news-release/2022/09/13/2515090/0/en/Life-Clips-to-Spin-Off-Cognitive-Apps-Subsidiary-to-Shareholders.html','Issuer announces intended Cognitive Apps spin-off; announcement not treated as proof of completed separation date.')
lp=[p('Mobeego','Single-use mobile-device battery.',M,'discontinued',roles=['owner'],typ='product',sector='energy_storage',sub='batteries'),p('Aiki','Historical mental-health analytics and therapy-support app.',A,roles=['owner'],typ='product',sub='diagnostics',attributes={'relationship_scope':'historical_Cognitive_Apps_subsidiary','current_availability_and_rights':'unverified','regulatory_clearance':'not_established'},evidence=[A,S])]
B=ev('https://www.sec.gov/Archives/edgar/data/1690080/000121390024025262/ea0200233-10k_180lif.htm','180 Life Sciences describes repurposed off-the-shelf adalimumab development, synthetic CBD analogues and alpha7 nicotinic receptor platform. Not original ownership of Humira or founder prior employers drugs.')
