bp=[p('180LS adalimumab repurposing programme','Historical anti-TNF research for fibrosis and related indications.',B,roles=['developer'],attributes={'relationship_scope':'repurposing_research; not original_Humira_invention','company_program_status':'pharmaceutical_business_exited_2025'},evidence=[B,D]),p('180LS Synthetic CBD Analogues programme','Historical synthetic cannabinoid-analogue research.',B,roles=['developer'],attributes={'company_program_status':'pharmaceutical_business_exited_2025'},evidence=[B,D]),p('180LS alpha7nAChR programme','Historical nicotinic-receptor therapeutic research.',B,roles=['licensee'],attributes={'rights_returned':'Stanford University November 2024','current_successor_status':'unverified'},evidence=[B,D])]
cs=[company('Orzel Bialy S.A.',op,[O,OA],'Exact Pb2 battery-material grade captured. Pb0/Pb1 references describe primary smelters and not attributed. Custom calcium/antimony alloy grade codes and technical datasheets remain unresolved.'),company('Life Clips Inc',lp,[M,A,S],'Retired Mobeego battery and historical Aiki app captured; unrelated cameras and generic crypto exchange excluded. Cognitive Apps announced spin-off not treated as completed. Later rights, battery variants and other qualifying app identities require followup.'),company('180 Life Sciences Corp',bp,[B,D],'Three explicitly described historical research programmes captured without attributing Humira invention or founders earlier drugs. Current successor exited pharmaceutical commercialization; alpha7 rights returned to Stanford in November2024. Specific analogue identities and final TNF/CBD rights disposition require followup.')]
